const servicios = $input.all().map(item => item.json);
const datosCita = $('Normalizar datos').item.json;

const nombreBuscado = (datosCita.servicio || '').toLowerCase().trim();

const servicioEncontrado = servicios.find(servicio => {
  const nombre = (servicio.nombre || '').toLowerCase().trim();

  return (
    nombre.includes(nombreBuscado) ||
    nombreBuscado.includes(nombre)
  );
});

if (!servicioEncontrado) {
  return [
    {
      json: {
        ...datosCita,
        servicioEncontrado: false,
        mensaje: `No encontré el servicio "${datosCita.servicio}".`
      }
    }
  ];
}

return [
  {
    json: {
      ...datosCita,
      servicioEncontrado: true,

      // ID real que viene desde tu backend
      idServicio: servicioEncontrado.id_servicio,

      // Duración real que viene desde tu backend
      duracionServicioMin: servicioEncontrado.duracion_minutos,

      // Precio real
      precioTotal: servicioEncontrado.precio_total,

      servicioDetalle: servicioEncontrado
    }
  }
];

const output = $json.output || $json.text || $json.response || '{}';

let data;

try {
  data = typeof output === 'string' ? JSON.parse(output) : output;
} catch (error) {
  data = {
    intencion: 'agendar_cita',
    servicio: '',
    fecha: '',
    hora: '',
    idCliente: $('Webhook').item.json.body.idCliente || '',
    idServicio: '',
    idStaff: '',
    datosFaltantes: ['servicio', 'fecha', 'hora']
  };
}

data.idCliente = data.idCliente || $('Webhook').item.json.body.idCliente || '';
data.idStaff = data.idStaff || $('Webhook').item.json.body.idStaff || '';

data.datosFaltantes = data.datosFaltantes || [];

if (!data.idCliente) data.datosFaltantes.push('cliente');
if (!data.idStaff) data.datosFaltantes.push('staff');
if (!data.servicio && !data.idServicio) data.datosFaltantes.push('servicio');
if (!data.fecha) data.datosFaltantes.push('fecha');
if (!data.hora) data.datosFaltantes.push('hora');

data.datosFaltantes = [...new Set(data.datosFaltantes)];

return [
  {
    json: data
  }
];

