const inputItems = $input.all();

const datosCita = $('Buscar servicio solicitado').item.json;

let slots = [];

for (const item of inputItems) {
  if (Array.isArray(item.json)) {
    slots.push(...item.json);
  } else if (Array.isArray(item.json.body)) {
    slots.push(...item.json.body);
  } else if (item.json.inicio) {
    slots.push(item.json);
  }
}

const fecha = datosCita.fecha;
const hora = datosCita.hora;

const fechaHoraSolicitada = `${fecha}T${hora}:00-04:00`;
const solicitadoMs = new Date(fechaHoraSolicitada).getTime();

const horariosDisponibles = slots.map(slot => {
  const fechaInicio = new Date(slot.inicio);

  return fechaInicio.toLocaleTimeString('es-CL', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
    timeZone: 'America/Santiago',
  });
});

const slotEncontrado = slots.find(slot => {
  const inicioMs = new Date(slot.inicio).getTime();
  return inicioMs === solicitadoMs;
});

if (!slotEncontrado) {
  return [
    {
      json: {
        ...datosCita,
        disponible: false,
        fechaHoraInicio: fechaHoraSolicitada,
        horariosDisponibles,
        mensaje: horariosDisponibles.length > 0
          ? `El horario ${hora} no está disponible.`
          : `No hay horarios disponibles para esa fecha.`
      }
    }
  ];
}

return [
  {
    json: {
      ...datosCita,
      disponible: true,
      fechaHoraInicio: fechaHoraSolicitada,
      slot: slotEncontrado,
      horariosDisponibles
    }
  }
];

