      idServicio: servicioEncontrado.id_servicio,

      // Duración real que viene desde tu backend
      duracionServicioMin: servicioEncontrado.duracion_minutos,

      // Precio real
      precioTotal: servicioEncontrado.precio_total,

      servicioDetalle: servicioEncontrado
    }
  }
];

// Obtener de forma segura los datos recibidos por el Webhook.
const webhookJson = $('Webhook').item.json || {};
const webhookBody = webhookJson.body || webhookJson;

// Obtener la respuesta generada por el AI Agent.
let output =
  $json.output ??
  $json.text ??
  $json.response ??
  '{}';

let data;

// Intentar convertir la respuesta del agente en JSON.
try {
  if (typeof output === 'string') {
    output = output
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');

    data = JSON.parse(output);
  } else {
    data = output;
  }

  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error('La respuesta del agente no es un objeto JSON válido');
  }
} catch (error) {
  data = {
    intencion: 'agendar_cita',
    servicio: '',
    fecha: '',
    hora: '',
    idCliente: '',
    idServicio: '',
    idStaff: '',
    datosFaltantes: []
  };
}

// Función para normalizar textos.
const normalizarTexto = (valor) => {
  return typeof valor === 'string'
    ? valor.trim()
    : '';
};

// Normalizar intención.
const intencionesPermitidas = [
  'agendar_cita',
  'consultar_disponibilidad',
  'consultar_citas',
  'cancelar_cita',
  'saludo',
  'desconocida'
];

data.intencion = normalizarTexto(data.intencion) || 'agendar_cita';

if (!intencionesPermitidas.includes(data.intencion)) {
  data.intencion = 'desconocida';
}

// Normalizar datos extraídos por el agente.
data.servicio = normalizarTexto(data.servicio);
data.fecha = normalizarTexto(data.fecha);
data.hora = normalizarTexto(data.hora);

// Los identificadores enviados por el sistema tienen prioridad.
// Esto evita que la IA invente o modifique los UUID.
data.idCliente =
  normalizarTexto(webhookBody.idCliente) ||
  normalizarTexto(data.idCliente);

data.idServicio =
  normalizarTexto(webhookBody.idServicio) ||
  normalizarTexto(data.idServicio);

data.idStaff =
  normalizarTexto(webhookBody.idStaff) ||
  normalizarTexto(data.idStaff);

// Validar formato básico de fecha YYYY-MM-DD.
const formatoFechaValido = /^\d{4}-\d{2}-\d{2}$/;

if (data.fecha && !formatoFechaValido.test(data.fecha)) {
  data.fecha = '';
}

// Validar formato básico de hora HH:mm.
const formatoHoraValido = /^([01]\d|2[0-3]):[0-5]\d$/;

if (data.hora && !formatoHoraValido.test(data.hora)) {
  data.hora = '';
}

// Reconstruir datosFaltantes desde cero.
// No confiar completamente en el arreglo generado por la IA.
const datosFaltantes = [];

if (!data.idCliente) {
  datosFaltantes.push('cliente');
}

if (!data.servicio && !data.idServicio) {
  datosFaltantes.push('servicio');
}

if (!data.fecha) {
  datosFaltantes.push('fecha');
}

if (!data.hora) {
  datosFaltantes.push('hora');
}

// IMPORTANTE:
// idStaff no es obligatorio en esta etapa.
// Se obtendrá después consultando:
// GET /api/agenda/servicios/{idServicio}/staff

data.datosFaltantes = datosFaltantes;

return [
  {
    json: data
  }
];
